  <sc-if value="{{v.Home}}" hint-placeholder-val="{{ false }}"><div style="width: 390px; height: 844px; animation: {{trans}}"><dc-import name="Home" app="{{app}}" set-val="{{setVal}}" ir-para="{{irPara}}" hint-size="390px,844px"></dc-import></div></sc-if>
